CR = (CR & ~PDDS) | LPDS;   /* bit1=0 bit0=1 */
SCR |= SLEEPDEEP;           /* bit2 */
MCU_BARRIER();
MCU_WFI();

/* 醒来：时钟已经在 16MHz 上跑了 */
sys_tick_load = 16000000 / 1000 - 1;

